{
  "name": "workboard",
  "version": "0.0.0",
  "private": true,
  "type": "module",
  "scripts": {
    "start": "node server.js"
  }
}
import { createServer } from 'node:http';
import { readFile } from 'node:fs/promises';
import { DatabaseSync } from 'node:sqlite';
import { randomUUID } from 'node:crypto';
import { fileURLToPath } from 'node:url';
import path from 'node:path';

const here = path.dirname(fileURLToPath(import.meta.url));
const db = new DatabaseSync(process.env.DB_PATH || path.join(here, 'workboard.sqlite'));
db.exec(`CREATE TABLE IF NOT EXISTS projects (
  id TEXT PRIMARY KEY,
  name TEXT NOT NULL,
  created_at INTEGER NOT NULL
)`);
db.exec(`CREATE TABLE IF NOT EXISTS tasks (
  id TEXT PRIMARY KEY,
  project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
  title TEXT NOT NULL,
  completed INTEGER NOT NULL DEFAULT 0,
  created_at INTEGER NOT NULL
)`);

const listProjects = db.prepare('SELECT id, name FROM projects ORDER BY created_at, rowid');
const getProject = db.prepare('SELECT id, name FROM projects WHERE id = ?');
const addProject = db.prepare('INSERT INTO projects (id, name, created_at) VALUES (?, ?, ?)');
const listTasks = db.prepare('SELECT id, project_id AS projectId, title, completed FROM tasks WHERE project_id = ? ORDER BY created_at, rowid');
const addTask = db.prepare('INSERT INTO tasks (id, project_id, title, completed, created_at) VALUES (?, ?, ?, 0, ?)');
const updateTask = db.prepare('UPDATE tasks SET completed = ? WHERE id = ? AND project_id = ?');

async function readBody(request) {
  let body = '';
  for await (const chunk of request) body += chunk;
  return JSON.parse(body || '{}');
}

function sendJson(response, status, value) {
  response.writeHead(status, { 'Content-Type': 'application/json; charset=utf-8' });
  response.end(JSON.stringify(value));
}

const server = createServer(async (request, response) => {
  const url = new URL(request.url, 'http://localhost');
  if (request.method === 'GET' && url.pathname === '/health') {
    return sendJson(response, 200, { status: 'ok' });
  }
  if (request.method === 'GET' && url.pathname === '/api/projects') {
    return sendJson(response, 200, listProjects.all());
  }
  if (request.method === 'POST' && url.pathname === '/api/projects') {
    try {
      const name = String((await readBody(request)).name ?? '').trim();
      if (!name) return sendJson(response, 400, { error: 'Project name is required' });
      const project = { id: randomUUID(), name };
      addProject.run(project.id, project.name, Date.now());
      return sendJson(response, 201, project);
    } catch {
      return sendJson(response, 400, { error: 'Invalid request' });
    }
  }
  const projectMatch = url.pathname.match(/^\/api\/projects\/([^/]+)$/);
  if (request.method === 'GET' && projectMatch) {
    const project = getProject.get(decodeURIComponent(projectMatch[1]));
    return project ? sendJson(response, 200, project) : sendJson(response, 404, { error: 'Project not found' });
  }
  const tasksMatch = url.pathname.match(/^\/api\/projects\/([^/]+)\/tasks$/);
  if (tasksMatch) {
    const projectId = decodeURIComponent(tasksMatch[1]);
    if (!getProject.get(projectId)) return sendJson(response, 404, { error: 'Project not found' });
    if (request.method === 'GET') return sendJson(response, 200, listTasks.all(projectId));
    if (request.method === 'POST') {
      try {
        const title = String((await readBody(request)).title ?? '').trim();
        if (!title) return sendJson(response, 400, { error: 'Task title is required' });
        const task = { id: randomUUID(), projectId, title, completed: 0 };
        addTask.run(task.id, projectId, title, Date.now());
        return sendJson(response, 201, task);
      } catch { return sendJson(response, 400, { error: 'Invalid request' }); }
    }
  }
  const taskMatch = url.pathname.match(/^\/api\/projects\/([^/]+)\/tasks\/([^/]+)$/);
  if (request.method === 'PATCH' && taskMatch) {
    try {
      const projectId = decodeURIComponent(taskMatch[1]);
      const taskId = decodeURIComponent(taskMatch[2]);
      const { completed } = await readBody(request);
      if (!getProject.get(projectId)) return sendJson(response, 404, { error: 'Project not found' });
      const result = updateTask.run(completed ? 1 : 0, taskId, projectId);
      return result.changes ? sendJson(response, 200, { status: 'ok' }) : sendJson(response, 404, { error: 'Task not found' });
    } catch { return sendJson(response, 400, { error: 'Invalid request' }); }
  }
  if (request.method === 'GET' && url.pathname === '/') {
    response.writeHead(200, { 'Content-Type': 'text/html; charset=utf-8' });
    return response.end(await readFile(path.join(here, 'index.html')));
  }
  if (request.method === 'GET' && url.pathname.startsWith('/projects/')) {
    response.writeHead(200, { 'Content-Type': 'text/html; charset=utf-8' });
    return response.end(await readFile(path.join(here, 'index.html')));
  }
  response.writeHead(404, { 'Content-Type': 'text/plain; charset=utf-8' });
  response.end('Not found');
});

const port = Number(process.env.PORT || 8080);
server.listen(port, '0.0.0.0', () => console.log(`Workboard listening on ${port}`));
<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>Workboard</title>
  <style>
    :root { color-scheme: light; font-family: system-ui, sans-serif; color: #17212b; background: #f4f7fa; }
    body { margin: 0; }
    main { max-width: 760px; margin: 48px auto; padding: 0 24px; }
    h1 { margin: 0 0 24px; font-size: 2rem; }
    form, .project-row, .task-row { background: white; border: 1px solid #d9e1e8; border-radius: 10px; padding: 20px; }
    form { display: grid; gap: 10px; margin-bottom: 20px; }
    label { font-weight: 600; }
    input { font: inherit; padding: 10px 12px; border: 1px solid #9eacb8; border-radius: 6px; }
    button { font: inherit; font-weight: 600; color: white; background: #1769aa; border: 0; border-radius: 6px; padding: 10px 14px; cursor: pointer; }
    button:hover { background: #10568e; }
    .project-row { display: flex; align-items: center; justify-content: space-between; margin: 10px 0; }
    .task-row { display: flex; align-items: center; gap: 12px; margin: 10px 0; }
    .task-row input { padding: 0; }
    select { font: inherit; padding: 8px; border: 1px solid #9eacb8; border-radius: 6px; }
    .alert { color: #a12622; margin: 0 0 16px; }
  </style>
</head>
<body>
  <main id="app"></main>
  <script type="module">
    const app = document.querySelector('#app');

    async function loadProjects() {
      const response = await fetch('/api/projects');
      return response.json();
    }

    function showList(message = '') {
      app.innerHTML = `
        <h1>Workboard</h1>
        <form id="create-project">
          <label for="project-name">Project name</label>
          <input id="project-name" name="name" type="text" autocomplete="off">
          <button type="submit">Create project</button>
        </form>
        <p class="alert" role="alert"${message ? '' : ' hidden'}>${message}</p>
        <section id="projects" aria-label="Projects"></section>`;
      const form = app.querySelector('#create-project');
      form.addEventListener('submit', async (event) => {
        event.preventDefault();
        const name = new FormData(form).get('name').trim();
        if (!name) {
          showList('Project name is required');
          return;
        }
        const response = await fetch('/api/projects', {
          method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ name })
        });
        if (response.ok) showList();
      });
      loadProjects().then((projects) => {
        const list = app.querySelector('#projects');
        for (const project of projects) {
          const row = document.createElement('div');
          row.className = 'project-row';
          row.dataset.testid = 'project-row';
          const name = document.createElement('span');
          name.textContent = project.name;
          const open = document.createElement('button');
          open.type = 'button';
          open.textContent = 'Open project';
          open.addEventListener('click', () => { location.href = `/projects/${encodeURIComponent(project.id)}`; });
          row.append(name, open);
          list.append(row);
        }
      });
    }

    async function showProject(id) {
      const response = await fetch(`/api/projects/${encodeURIComponent(id)}`);
      if (!response.ok) { showList(); return; }
      const project = await response.json();
      app.innerHTML = `
        <button type="button" id="back">Projects</button><h1></h1>
        <form id="create-task">
          <label for="task-title">Task title</label>
          <input id="task-title" name="title" type="text" autocomplete="off">
          <button type="submit">Create task</button>
        </form>
        <p class="alert" role="alert" hidden></p>
        <label for="task-filter">Task filter</label>
        <select id="task-filter"><option>All</option><option>Open</option><option>Completed</option></select>
        <section id="tasks" aria-label="Tasks"></section>`;
      app.querySelector('#back').addEventListener('click', () => { location.href = '/'; });
      app.querySelector('h1').textContent = project.name;
      const form = app.querySelector('#create-task');
      const alert = app.querySelector('[role="alert"]');
      const filter = app.querySelector('#task-filter');
      async function renderTasks() {
        const tasks = await (await fetch(`/api/projects/${encodeURIComponent(id)}/tasks`)).json();
        const visible = tasks.filter((task) => filter.value === 'All' ||
          (filter.value === 'Open' ? !task.completed : Boolean(task.completed)));
        const list = app.querySelector('#tasks');
        list.replaceChildren();
        for (const task of visible) {
          const row = document.createElement('div');
          row.className = 'task-row';
          row.dataset.testid = 'task-row';
          const checkbox = document.createElement('input');
          checkbox.type = 'checkbox';
          checkbox.checked = Boolean(task.completed);
          checkbox.setAttribute('aria-label', `Complete ${task.title}`);
          checkbox.addEventListener('change', async () => {
            await fetch(`/api/projects/${encodeURIComponent(id)}/tasks/${encodeURIComponent(task.id)}`, {
              method: 'PATCH', headers: { 'Content-Type': 'application/json' },
              body: JSON.stringify({ completed: checkbox.checked })
            });
            await renderTasks();
          });
          const title = document.createElement('span');
          title.textContent = task.title;
          row.append(checkbox, title);
          list.append(row);
        }
      }
      filter.addEventListener('change', renderTasks);
      form.addEventListener('submit', async (event) => {
        event.preventDefault();
        const title = new FormData(form).get('title').trim();
        if (!title) { alert.textContent = 'Task title is required'; alert.hidden = false; return; }
        const response = await fetch(`/api/projects/${encodeURIComponent(id)}/tasks`, {
          method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ title })
        });
        if (response.ok) { form.reset(); alert.hidden = true; await renderTasks(); }
      });
      await renderTasks();
    }

    const match = location.pathname.match(/^\/projects\/([^/]+)\/?$/);
    if (match) showProject(decodeURIComponent(match[1]));
    else showList();
  </script>
</body>
</html>
